{"command": "cd /workspace
timeout 5 python3 <<'PY'
import os, pty, select, struct, fcntl, termios, time, sys

def runpty(w,h, args):
    pid, fd = pty.fork()
    if pid == 0:
        os.execv("/workspace/executable", ["executable"]+args)
    else:
        try:
            fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack("HHHH", h, w, 0, 0))
        except Exception as e:
            print("set size failed", e)
        time.sleep(1.2)
        data=b""
        while True:
            r,_,_=select.select([fd], [], [], 0.3)
            if not r:
                break
            try:
                chunk=os.read(fd, 8192)
                if not chunk:
                    break
                data+=chunk
            except OSError as e:
                break
        print(f"w={w} h={h} args={args} data={data[:3000]!r}")
        # check if child exited?
        try:
            pid2, status = os.waitpid(pid, os.WNOHANG)
            print(f"waitpid pid2={pid2} status={status} exit={os.waitstatus_to_exitcode(status) if pid2!=0 else 'running'}")
            if pid2==0:
                print("still running, killing")
                os.kill(pid, 9)
                pid2, status = os.waitpid(pid, 0)
                print(f"after kill status={status} exit={os.waitstatus_to_exitcode(status)}")
        except Exception as e:
            print("wait", e)
        try:
            os.close(fd)
        except: pass

runpty(120,30, ["--help"])
PY"}

