# ---------- utilities ----------

def get_data_dir():
    xdg = os.environ.get("XDG_DATA_HOME")
    if xdg and xdg.strip():
        return os.path.join(xdg, "felix")
    home = os.environ.get("HOME") or os.path.expanduser("~")
    return os.path.join(home, ".local", "share", "felix")

def get_runtime_dir():
    xdg = os.environ.get("XDG_RUNTIME_DIR")
    if xdg and xdg.strip():
        return os.path.join(xdg, "felix")
    tmp = os.environ.get("TMPDIR")
    if tmp and tmp.strip():
        return os.path.join(tmp, "felix")
    return "/tmp/felix"

def get_config_dir():
    # Linux: XDG_CONFIG_HOME/felix or ~/.config/felix
    xdg = os.environ.get("XDG_CONFIG_HOME")
    if xdg and xdg.strip():
        return os.path.join(xdg, "felix")
    home = os.environ.get("HOME") or os.path.expanduser("~")
    return os.path.join(home, ".config", "felix")

def format_size(sz):
    try:
        sz = int(sz)
    except:
        sz = 0
    if sz < 1000:
        return f"{sz}B"
    elif sz < 1000000:
        return f"{sz//1000}KB"
    elif sz < 1000000000:
        return f"{sz//1000000}MB"
    elif sz < 1000000000000:
        return f"{sz//1000000000}GB"
    else:
        return f"{sz//1000000000000}TB"

def format_perm(path, st=None):
    try:
        if st is None:
            st = os.stat(path, follow_symlinks=False) if os.path.islink(path) else os.stat(path)
            # For symlink, original shows target's perm? Let's check: symlink perm is 777? But status for symlink shows linked, not perm. So only for non-symlink.
            # For regular, use st_mode & 0o777
        mode = st.st_mode & 0o777
        return oct(mode)[2:]
    except:
        return "???"

def get_ext(name):
    # last extension after dot, not counting leading dot
    if name.startswith(".") and name.count(".") == 1:
        return ""
    if "." in name:
        # handle trailing dot? e.g., "file." -> ""? Probably ""
        parts = name.rsplit(".", 1)
        if parts[1] == "":
            return ""
        return parts[1]
    return ""

def natural_key(s):
    # split into digit and non-digit
    parts = re.split(r'(\d+)', s)
    key = []
    for p in parts:
        if p.isdigit():
            # numeric: compare by length then value? To handle leading zeros? Use int
            try:
                key.append((0, int(p), len(p)))
            except:
                key.append((1, p.lower()))
        else:
            key.append((1, p.lower()))
    return key

def list_dir(cwd, show_hidden, sort_by):
    try:
        names = os.listdir(cwd)
    except:
        return []
    items = []
    for name in names:
        if not show_hidden and name.startswith("."):
            continue
        full = os.path.join(cwd, name)
        # lstat for symlink check
