                # e.g., broken symlink: stat fails
                mtime = lst.st_mtime if hasattr(lst, 'st_mtime') else 0
                size = lst.st_size
                try:
                    perm = oct(lst.st_mode & 0o777)[2:]
                except:
                    perm = "???"
                is_dir = False
            # date string
            try:
                dt = datetime.datetime.fromtimestamp(mtime)
                datestr = dt.strftime("%Y-%m-%d %H:%M")
            except:
                datestr = "---- -- -- --:--"
            # target for symlink
            target = None
            if is_link:
                try:
                    target = os.readlink(full)
                    # resolve relative?
                    if not os.path.isabs(target):
                        target = os.path.join(cwd, target)
                    # normalize? Keep as absolute? Original shows absolute: "linked to: /tmp/fxtest/subdir"
                    # For relative link, it shows absolute? Let's see: linkdir -> /tmp/fxtest/subdir (absolute). Good.
                    # If link is relative, original probably shows absolute? We'll show absolute normalized.
                    target = os.path.normpath(target)
                except:
                    target = "(invalid path)"
                # check if target exists? If not, status shows "(invalid path)"? Actually status shows "linked to: (invalid path)" for broken?
                # From earlier: broken selected shows " linked to: (invalid path)" – not the target path, just that string.
                # Wait: For broken, target is /nonexistent_target_xyz, but status shows "(invalid path)" not the path. Let's verify.
                # Earlier: broken showed " linked to: (invalid path)" – yes, not the target. So for broken, show that.
                try:
                    if not os.path.exists(full):
                        # broken (exists follows link returns False)
                        target_display = "(invalid path)"
                    else:
                        target_display = target
                except:
                    target_display = "(invalid path)"
            else:
                target_display = None
            items.append({
                "name": name,
                "full": full,
                "is_link": is_link,
                "is_dir": is_dir,
                "mtime": mtime,
                "size": size,
                "perm": perm,
                "datestr": datestr,
                "target": target,
                "target_display": target_display if is_link else None,
                "lstat": lst,
            })
        except Exception as e:
            continue
    # sort
    if sort_by == "Modified":
        # sort by mtime? Need to check order: t toggles name <-> modified time. Which order? Probably newest first? Let's assume newest first? Or oldest? Need to probe.
        # For now, sort by mtime descending? Let's test later. For now, sort by mtime with dirs? Or all by mtime?
        # Original with t pressed showed same order (maybe because mtimes same)? Need to test with different mtimes.
        # We'll implement: sort by mtime descending, dirs? Or same dirs-first? Probably still dirs-first? Or maybe pure mtime? Let's assume pure mtime descending.
        # To be safe, we'll keep dirs-first? Hmm.
        # Let's implement as: sort by mtime descending (newest first), stable?
        items.sort(key=lambda x: x["mtime"], reverse=True)
    else:
        # Name: dirs first, then natural sort
        dirs = [x for x in items if x["is_dir"]]
        files = [x for x in items if not x["is_dir"]]
        dirs.sort(key=lambda x: natural_key(x["name"]))
        files.sort(key=lambda x: natural_key(x["name"]))
        items = dirs + files
    return items

def get_terminal_size():
    for fd in (1, 2, 0):
        try:
            sz = os.get_terminal_size(fd)
            return (sz.columns, sz.lines)
        except OSError:
            continue
    try:
        # try /dev/tty
        tty = os.open("/dev/tty", os.O_RDONLY)
        try:
            sz = os.get_terminal_size(tty)
            os.close(tty)
            return (sz.columns, sz.lines)
        except OSError:
            try:
                os.close(tty)
            except:
                pass
    except:
        pass
    return None

