    # ----- file ops -----
    def do_yank(self, indices, register="0", append=False):
        targets = [self.items[i] for i in sorted(indices) if 0 <= i < len(self.items)]
        paths = [t["full"] for t in targets]
        if not paths:
            return
        if append:
            if register not in self.registers:
                self.registers[register]=[]
            self.registers[register].extend(paths)
            self.register_cut[register]=False
        else:
            self.registers[register]=paths[:]
            self.register_cut[register]=False
        n=len(paths)
        self.message = f"{n} item{'s' if n!=1 else ''} yanked."

    def do_delete_yank(self, indices, register="0", append=False):
        targets = [self.items[i] for i in sorted(indices) if 0 <= i < len(self.items)]
        if not targets:
            return
        paths = [t["full"] for t in targets]
        trash = self.trash_path()
        try:
            os.makedirs(trash, exist_ok=True)
        except:
            pass
        ts = int(time.time())
        moved=[]
        for t in targets:
            src=t["full"]
            base=os.path.basename(src)
            dst_name=f"{ts}_{base}"
            dst=os.path.join(trash, dst_name)
            cnt=0
            while os.path.exists(dst):
                cnt+=1
                dst=os.path.join(trash, f"{ts}_{base}_{cnt}")
            try:
                shutil.move(src, dst)
                moved.append((src,dst))
            except Exception as e:
                self.message=f"Failed to delete: {e}"
                self.refresh_items()
                return
        # store trash paths in register
        tpaths=[d for s,d in moved]
        if append:
            if register not in self.registers:
                self.registers[register]=[]
            self.registers[register].extend(tpaths)
            self.register_cut[register]=True
        else:
            self.registers[register]=tpaths[:]
