            try:
                exists = os.path.exists(p)
            except:
                exists=False
            if not exists:
                # Invalid path: print \n to stdout, error to stderr
                try:
                    sys.stdout.write("\n")
                    sys.stdout.flush()
                except:
                    pass
                eprint(f"Invalid path: {p}\n`fx -h` shows help.\n")
                return
            # exists, check isdir
            try:
                isdir = os.path.isdir(p)
            except:
                isdir=False
            if not isdir:
